// Clipboard history model (2026-10-20): the items and the pure rules of the list. No AppKit:
// ClipboardHistoryManager reads the pasteboard, writes the files and applies these rules.
// Tests: Tests/EngineTests/ClipboardHistoryTests.swift.
//
// Rules:
// - Capture (`ClipboardCapture`): nothing is recorded when the pasteboard carries a "do not record"
//   type (nspasteboard.org concealed / transient / auto-generated, 1Password, …), when the
//   frontmost app is excluded, or when the contents are whitespace only. Priority: copied files
//   (when file capture is on), else text (never for a file copy — Finder also puts the file name
//   on the pasteboard), else an image (when image capture is on, PNG ≤ `maxImageBytes`). Text is
//   capped at `maxTextLength` characters.
// - Dedupe (`ClipboardHistory.record`): only CONSECUTIVE duplicates merge — a copy with the same
//   content as the newest entry (same text, same file paths, same image hash) refreshes that entry's
//   date and source instead of adding a row. The same content further down is added again.
// - Limit: newest first, at most `limit` entries (at least 1); the oldest are dropped.
// - Re-copy (`promote`): putting an entry back on the clipboard moves it to the top with a new date.
// - Pinning: there is none — every entry ages out under the limit.
// - Images are files named by `imageFileName`; every operation that drops entries returns the
//   image files no remaining entry references, for the manager to delete.
import Foundation

struct ClipboardItem: Codable, Identifiable, Hashable {
    enum Kind: String, Codable {
        case text
        case image
        case files
    }

    var id = UUID()
    var kind: Kind
    var date = Date()
    /// `.text`: the copied string (capped at `ClipboardCapture.maxTextLength`).
    var text: String?
    /// `.files`: paths of the copied file URLs.
    var filePaths: [String]?
    /// `.image`: file name of the PNG in the images directory, its pixel size and a content hash.
    var imageFileName: String?
    var imageWidth: Double?
    var imageHeight: Double?
    var imageHash: String?
    /// Frontmost app when the copy was noticed (best effort; the pasteboard has no owner info).
    var sourceBundleID: String?
    var sourceAppName: String?

    /// One-line summary for lists.
    var summary: String {
        switch kind {
        case .text:
            let collapsed = (text ?? "")
                .split(whereSeparator: \.isNewline)
                .map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { !$0.isEmpty }
                .joined(separator: " ")
            return collapsed
        case .image:
            if let w = imageWidth, let h = imageHeight {
                return String(localized: "Image \(String(Int(w))) × \(String(Int(h)))")
            }
            return String(localized: "Image")
        case .files:
            let names = (filePaths ?? []).map { ($0 as NSString).lastPathComponent }
            if names.count <= 1 { return names.first ?? "" }
            return String(localized: "\(names[0]) and \(names.count - 1) more")
        }
    }

    /// SF Symbol for the content type.
    var symbolName: String {
        switch kind {
        case .text:
            if let text, Self.isWebURL(text) { return "link" }
            return "doc.text"
        case .image:
            return "photo"
        case .files:
            return (filePaths?.count ?? 0) > 1 ? "doc.on.doc" : "doc"
        }
    }

    static func isWebURL(_ string: String) -> Bool {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace), let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased() else { return false }
        return (scheme == "http" || scheme == "https") && url.host != nil
    }

    /// Whether two items have the same content (used to merge consecutive duplicates).
    func hasSameContent(as other: ClipboardItem) -> Bool {
        guard kind == other.kind else { return false }
        switch kind {
        case .text: return text == other.text
        case .image: return imageHash != nil && imageHash == other.imageHash
        case .files: return filePaths == other.filePaths
        }
    }
}

/// What to record from the pasteboard.
enum ClipboardCapture {
    static let maxTextLength = 100_000
    static let maxImageBytes = 5 * 1024 * 1024

    /// Pasteboard types that mark contents that must not be recorded (nspasteboard.org).
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    /// Whether the pasteboard may be recorded at all: it has contents, none of them marked
    /// "do not record", and the frontmost app is not excluded.
    static func mayRecord(types: [String], sourceBundleID: String?, excludedBundleIDs: [String]) -> Bool {
        guard !types.isEmpty, !types.contains(where: ignoredTypes.contains) else { return false }
        if let sourceBundleID, excludedBundleIDs.contains(sourceBundleID) { return false }
        return true
    }

    enum Choice: Equatable {
        case files, text, image, nothing
    }

    /// Which representation to record. `hasFileURLType`: the pasteboard has the file-URL type;
    /// `hasFileURLs`: file URLs could be read from it; `string`: its plain text; `hasImage`: whether
    /// it holds an image of an acceptable size (only asked when an image would be recorded — reading
    /// it is the expensive part).
    static func choose(hasFileURLType: Bool, hasFileURLs: Bool, string: String?, hasImage: () -> Bool,
                       captureFiles: Bool, captureImages: Bool) -> Choice {
        if captureFiles, hasFileURLType, hasFileURLs { return .files }
        if !hasFileURLType, let string, !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return .text }
        if captureImages, !hasFileURLType, hasImage() { return .image }
        return .nothing
    }

    /// A text item (capped at `maxTextLength` characters), nil for whitespace-only text.
    static func textItem(_ string: String, date: Date = Date()) -> ClipboardItem? {
        guard !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        return ClipboardItem(kind: .text, date: date, text: String(string.prefix(maxTextLength)))
    }
}

/// The history list (newest first) and its rules.
struct ClipboardHistory: Equatable {
    private(set) var items: [ClipboardItem]

    init(items: [ClipboardItem] = []) { self.items = items }

    static func normalizedLimit(_ limit: Int) -> Int { max(1, limit) }

    /// The newest entry, when it is an image with this content hash (its file can be reused).
    func topImage(withHash hash: String) -> ClipboardItem? {
        guard let top = items.first, top.kind == .image, top.imageHash == hash else { return nil }
        return top
    }

    /// Records a copy: merges it into the newest entry when the content is the same, else adds it on
    /// top and applies the limit. Returns the image files no longer referenced.
    @discardableResult
    mutating func record(_ item: ClipboardItem, limit: Int) -> [String] {
        if let top = items.first, top.hasSameContent(as: item) {
            // consecutive duplicate: keep one entry, refresh its time and source
            items[0].date = item.date
            items[0].sourceBundleID = item.sourceBundleID ?? top.sourceBundleID
            items[0].sourceAppName = item.sourceAppName ?? top.sourceAppName
            return []
        }
        items.insert(item, at: 0)
        return trim(to: limit)
    }

    /// Drops the oldest entries beyond `limit`. Returns the image files no longer referenced.
    @discardableResult
    mutating func trim(to limit: Int) -> [String] {
        let limit = Self.normalizedLimit(limit)
        guard items.count > limit else { return [] }
        let dropped = Array(items[limit...])
        items.removeSubrange(limit...)
        return unreferencedImages(of: dropped)
    }

    /// Moves the entry to the top with a new date (it was put back on the clipboard). Returns false

    @discardableResult
    mutating func promote(id: UUID, date: Date) -> Bool {
        guard let index = items.firstIndex(where: { $0.id == id }) else { return false }
        var moved = items.remove(at: index)
        moved.date = date
        items.insert(moved, at: 0)
        return true
    }

    /// Returns the image files no longer referenced.
    @discardableResult
    mutating func remove(id: UUID) -> [String] {
        let removed = items.filter { $0.id == id }
        items.removeAll { $0.id == id }
        return unreferencedImages(of: removed)
    }

    /// Returns the image files no longer referenced.
    @discardableResult
    mutating func removeAll() -> [String] {
        let old = items
        items.removeAll()
        return unreferencedImages(of: old)
    }

    /// Keeps the loaded entries whose content still exists (an image entry needs its file).
    mutating func dropMissingImages(fileExists: (String) -> Bool) {
        items = items.filter { item in
            guard item.kind == .image else { return true }
            guard let name = item.imageFileName else { return false }
            return fileExists(name)
        }
    }

    /// Image files referenced by the list.
    var referencedImageFiles: Set<String> { Set(items.compactMap(\.imageFileName)) }

    /// Image files of `dropped` that no remaining entry references (each name once).
    private func unreferencedImages(of dropped: [ClipboardItem]) -> [String] {
        let referenced = referencedImageFiles
        var seen = Set<String>()
        return dropped.compactMap(\.imageFileName).filter { !referenced.contains($0) && seen.insert($0).inserted }
    }
}
